@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if the graph is already bipartite
    if (isBipartite(target)) {
        return;
    }

    // Create a map to store the bipartition
    Map<V, Integer> bipartition = new HashMap<>();

    // Initialize the bipartition with the current graph
    for (V vertex : target.getVertices()) {
        bipartition.put(vertex, 0);
    }

    // Iterate through the graph and move vertices to other partition
    for (E edge : target.getEdges()) {
        V source = target.getEdgeSource(edge);
        V target = target.getEdgeTarget(edge);

        // Check if the edge is between two vertices in the same partition
        if (bipartition.get(source) == bipartition.get(target)) {
            // Move one of the vertices to the other partition
            bipartition.put(source, 1 - bipartition.get(source));
            bipartition.put(target, 1 - bipartition.get(target));
        }
    }

    // Check if the graph is now bipartite
    if (isBipartite(target, bipartition)) {
        // Update the result map with the new bipartition
        for (V vertex : target.getVertices()) {
            resultMap.put(vertex, bipartition.get(vertex));
        }
    }
}

