   // Initialize a circulator to start at the given start node
   OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
   // Loop through the nodes in the direction specified until we find a node that satisfies the predicate or reach the stop node
   while (circulator.getNode() != stop && !predicate.test(circulator.getNode())) {
      circulator.move(dir);
   }
   // Return the circulator at the node that satisfies the predicate or the stop node
   return circulator;
}

