 * Returns a pair of the computed suffix sum list and the sum of all elements in the {@code bounds} list.
 *
 * @param bounds  List of integers to compute suffix sum.
 * @return  Pair of the computed suffix sum list and the sum of all elements.
 */
 private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds}{
   // Initialize the suffix sum list as a new instance of ArrayList
   List<Integer> suffixSum = new ArrayList<Integer>(bounds.size());
   // Initialize the sum of all elements as 0
   long total = 0L;
   // Loop through the bounds list in reverse order
   for (int i = bounds.size() - 1; i >= 0; i--){
     // Get the current bound
     int bound = bounds.get(i);
     // Add the bound to the sum of all elements
     total += bound;
     // Add the total to the list of suffix sums
     suffixSum.add(total);
   }
   // Return the pair of the suffix sum list and the sum of all elements
   return new Pair<List<Integer>,Long>(suffixSum, total);
 }

