public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }

    String trimmedName = name.trim();
    if (trimmedName.isEmpty()) {
        return name;
    }

    int firstNonUppercaseIndex = -1;
    for (int i = 0; i < trimmedName.length(); i++) {
        char ch = trimmedName.charAt(i);
        if (ch >= 'a' && ch <= 'z') {
            firstNonUppercaseIndex = i;
            break;
        }
    }

    if (firstNonUppercaseIndex < 0) {
        return name;
    }

    return new StringBuilder(name).replace(0, firstNonUppercaseIndex + 1, trimmedName.substring(0, firstNonUppercaseIndex + 1)).toString();
}

