    String cleanRelativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;
    String[] pathParts = cleanPath.split("/");
    String[] relativePathParts = cleanRelativePath.split("/");
    int pathPartsLength = pathParts.length;
    int relativePathPartsLength = relativePathParts.length;
    if (pathPartsLength == 0 || relativePathPartsLength == 0) {
        return "";
    }
    // compute the common root of the two paths
    int commonRootLength = 0;
    for (int i = 0; i < pathPartsLength && i < relativePathPartsLength; i++) {
        if (!pathParts[i].equals(relativePathParts[i])) {
            break;
        }
        commonRootLength += pathParts[i].length() + 1;
    }
    // remove the common root from the path
    String[] newPathParts = new String[pathPartsLength - commonRootLength];
    System.arraycopy(pathParts, commonRootLength, newPathParts, 0, newPathParts.length);
    // add the relative path to the remaining path
