public String format(LoggingEvent event){

        // Initialize the formatted string to empty
        String formattedString = "";

        // Check if the event has a message
        if (event.getMessage() != null) {
            // Get the message from the event
            String message = event.getMessage().toString();

            // Replace any %5B or %5D in the message with [ and ]
            message = message.replace("%5B", "[");
            message = message.replace("%5D", "]");

            // Check if the message contains a MDC key value pair
            if (message.contains("MDC")) {
                // Get the MDC values from the event
                Map<String, String> mdcValues = event.getMDCPropertyMap();

                // Iterate over the MDC values and replace any keys with the corresponding values
                for (Map.Entry<String, String> entry : mdcValues.entrySet()) {
                    String key = entry.getKey();
                    String value = entry.getValue();
                    message = message.replace(key, value);
                }
            }

            // Set the formatted string to the message
            formattedString = message;
        }

        // Check if the event has a throwable
        if (event.getThrowableInformation() != null) {
            // Get the throwable from the event
            ThrowableInformation throwableInformation = event.getThrowableInformation();
            Throwable throwable = throwableInformation.getThrowable();

            // Convert the throwable to a string
            String throwableString = throwable.toString();

            // Check if the throwable string contains a MDC key value pair
            if (throwableString.contains("MDC")) {
                // Get the MDC values from the event
                Map<String, String> mdcValues = event.getMDCPropertyMap();

                // Iterate over the MDC values and replace any keys with the corresponding values
                for (Map.Entry<String, String> entry : mdcValues.entrySet()) {
                    String key = entry.getKey();
                    String value = entry.getValue();
                    throwableString = throwableString.replace(key, value);
                }
            }

            // Append the throwable string to the formatted string
            formattedString += throwableString;
        }

        // Check if the event has a logger
        if (event.getLoggerName() != null) {
            // Get the logger name from the event
            String loggerName = event.getLoggerName();

            // Replace any %5D or %5D in the logger name with [ and ]
            loggerName = loggerName.replace("%5B", "[");
            loggerName = loggerName.replace("%5D", "]");

            // Append the logger name to the formatted string
            formattedString += loggerName;
        }

        // Check if the event has a timestamp
        if (event.getTimeStamp() != null) {
            // Get the timestamp from the event
            long timestamp = event.getTimeStamp();

            // Create a date formatter
            SimpleDateFormat dateFormatter = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

            // Format the timestamp
            String timestampString = dateFormatter.format(timestamp);

            // Append the timestamp to the formatted string
            formattedString += timestampString;
        }

        // Return the formatted string
        return formattedString;
    }

