        String telnetMessage = convertToTelnet(message);
        // Send the message to the client
        client.sendMessage(telnetMessage);
      } catch (Exception e) {
        // If an exception occurs, log it and remove the client from the list
        logger.error("Error sending message to client: " + client.getSocketAddress(), e);
        removeClient(client);
      }
    }
  }
}

