@Override
public void accept(METRICS data) {
    // Internal cache for data
    Map<String, METRICS> cache = new HashMap<>();

    // Iterate through the data
    for (Map.Entry<String, METRICS> entry : data.entrySet()) {
        String metricName = entry.getKey();
        METRICS metricData = entry.getValue();

        // Check if the cache already contains the metric
        if (cache.containsKey(metricName)) {
            METRICS existingMetricData = cache.get(metricName);
            // Merge the data with the existing data
            existingMetricData.merge(metricData);
        } else {
            // Add the metric to the cache
            cache.put(metricName, metricData);
        }
    }
}

