public Mappings diffStructure(String tableName, Mappings mappings) {
    // Step 1: Extract the current table structure from the mappings
    Table table = mappings.getTable(tableName);
    Collection<String> currentFields = table.getColumns()
            .stream()
            .map(Column::getName)
            .collect(Collectors.toList());

    // Step 2: Extract the history table structure from the mappings
    Table historyTable = mappings.getTable(tableName + "_history");
    Collection<String> historyFields = historyTable.getColumns()
            .stream()
            .map(Column::getName)
            .collect(Collectors.toList());

    // Step 3: Compute the difference between the current and history fields
    Collection<String> diff = historyFields.stream()
            .filter(field -> !currentFields.contains(field))
            .collect(Collectors.toList());

    // Step 4: Create a new mappings object with the difference fields
    Mappings diffMappings = new Mappings();
    diffMappings.setTable(tableName, table);
    for (String field : diff) {
        diffMappings.addField(tableName, field);
    }

    return diffMappings;
}

