public static long compressTimeBucket(String timeBucket, int dayStep) {
   // Replace all non-numeric characters with a dot
   timeBucket = timeBucket.replace("[^\\d.]+", ".");
   // Split the timeBucket into an array of substrings
   String[] timeBucketParts = timeBucket.split("\\.");
   // Iterate over the substrings and extract the numerical parts
   for (String part : timeBucketParts) {
     if (!part.equals("")) {
       // If the substring is a date, replace the day value with the step value
       if (part.matches("^\\d{8}$")) {
         part = String.format("%s%02d", part.substring(0, 6), dayStep);
       }
       // If the substring is a time, replace the hour and minute values with the step value
       if (part.matches("^\\d{6}$")) {
         part = String.format("%s%02d%02d", part.substring(0, 4), dayStep, dayStep);
       }
     }
   }
   // Join the modified substrings back into a single string
   timeBucket = String.join(".", timeBucketParts);
   return timeBucket;
 }

