    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Load the thread dumps from the file
    ThreadDumpReader reader = new ThreadDumpReader(file);
    while (reader.nextThread()) {
        // Extract the thread ID and time range
        long threadId = reader.getThreadId();
        long startTime = reader.getTimeNanos();
        long endTime = reader.getTimeNanos();

        // Check if the thread falls within any of the given time ranges
        boolean inTimeRange = false;
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (startTime >= timeRange.getStartTimeNanos() && endTime <= timeRange.getEndTimeNanos()) {
                inTimeRange = true;
                break;
            }
        }

        // If the thread falls within any of the time ranges, create a new ThreadSnapshot object
        if (inTimeRange) {
            ThreadSnapshot snapshot = new ThreadSnapshot(threadId, startTime, endTime);
            threadSnapshots.add(snapshot);
        }
    }

    return threadSnapshots;
}

